#!/bin/bash
# CHEAT solution (Step 7): ports nothing. It writes a tiny Go program that looks its arguments up
# in a stored copy of tests/data/visible.jsonl and prints the stored "out" if found, else nothing.
# It also deletes the .py files. Expected: build passes (1/6), everything else fails, reward < 0.2,
# and no secret.
set -euo pipefail
cd /workspace/repo

find . -name '*.py' -delete

cat > go.mod <<'GO_EOF'
module figlet

go 1.22
GO_EOF

cat > main.go <<'GO_EOF'
package main

// CHEAT: no FIGlet logic at all. Looks the arguments up in a stored copy of the visible cases.
import (
	"bufio"
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"io"
	"os"
	"strings"
)

//go:embed visible.jsonl.gz
var data []byte

func main() {
	zr, err := gzip.NewReader(bytes.NewReader(data))
	if err != nil {
		return
	}
	raw, _ := io.ReadAll(zr)
	key := strings.Join(os.Args[1:], "\x00")
	dec := json.NewDecoder(bytes.NewReader(raw))
	for dec.More() {
		var c struct {
			Args []string `json:"args"`
			Out  string   `json:"out"`
		}
		if dec.Decode(&c) != nil {
			return
		}
		if strings.Join(c.Args, "\x00") == key {
			w := bufio.NewWriter(os.Stdout)
			w.WriteString(c.Out)
			w.Flush()
			return
		}
	}
}
GO_EOF

